package com.order.order_service.controller;
import com.order.order_service.entity.OrderStatus;import com.order.order_service.service.*;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/orders") public class OrderQueryController {private final OrderQueryService queries;private final OrderService orders;public OrderQueryController(OrderQueryService q,OrderService o){queries=q;orders=o;}
 @GetMapping public Map<String,Object> mine(@AuthenticationPrincipal Jwt jwt){var rows=queries.mine(uid(jwt));return Map.of("content",rows,"totalElements",rows.size());}
 @GetMapping("/restaurant") public Map<String,Object> restaurant(@AuthenticationPrincipal Jwt jwt){role(jwt,"ROLE_RESTAURANT_OWNER","ROLE_ADMIN");var rows="ROLE_ADMIN".equals(jwt.getClaimAsString("role"))?queries.all():queries.ownerOrders(uid(jwt));return Map.of("content",rows,"totalElements",rows.size());}
 @GetMapping("/{id}") public Map<String,Object> one(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var row=queries.one(id);if(!Objects.equals(((Number)row.get("userId")).longValue(),uid(jwt))&&!staff(jwt))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You cannot access this order");return row;}
 @PutMapping("/{id}/status") public Map<String,Object> status(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,String> body){role(jwt,"ROLE_RESTAURANT_OWNER","ROLE_ADMIN");try{orders.applyDeliveryStatus(id,OrderStatus.valueOf(Objects.requireNonNull(body.get("status"))));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid order status",e);}return queries.one(id);}
 @GetMapping("/{id}/driver-location") public Map<String,Object> location(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){one(jwt,id);return queries.driverLocation(id,jwt.getTokenValue());}
 private long uid(Jwt jwt){return Long.parseLong(jwt.getClaim("userId").toString());}private boolean staff(Jwt jwt){String r=jwt.getClaimAsString("role");return "ROLE_ADMIN".equals(r)||"ROLE_RESTAURANT_OWNER".equals(r);}private void role(Jwt jwt,String... roles){if(Arrays.stream(roles).noneMatch(x->x.equals(jwt.getClaimAsString("role"))))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Insufficient role");}
}
